importScripts('physics.js','scan.js','orbit.js');let job=null,generation=0;
onmessage=e=>{let m=e.data;if(m.type==='stop'){generation++;job=null;return;}if(m.type!=='trial')return;let token=++generation;try{let initial=Scan.initial(m.config.radius,m.ordinal);job=Physics.create(initial,m.config);function tick(){if(token!==generation)return;try{if(job.advance(2000)){let r=job.result;r.orbit=Orbit.analyze(r);if(r.orbit.detected)r.outcome='Orbit candidate';postMessage({type:'result',result:r,token:m.token});job=null;}else setTimeout(tick,0);}catch(err){postMessage({type:'error',message:err.message,token:m.token});}}tick();}catch(err){postMessage({type:'error',message:err.message,token:m.token});}};
